from pathlib import Path
import base64,difflib,hashlib,json,os,re,shutil,subprocess
R=Path('/srv/android/asus-minimal-platform-build-r3-20261108');F=Path('/srv/android/asus-minimal-platform-build-r2-20261108');K=R/'kernel';O=R/'out';E=R/'evidence'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert not R.exists()
assert sha(F/'out/.config')=='6f8abd4290b19aad386770200825d3065e74fd8fb311d4b1b20c7af2cc621dc6'
free=shutil.disk_usage('/srv/android').free;sizes={n:int(subprocess.check_output(['du','-sb',str(F/n)],text=True).split()[0]) for n in ['kernel','out']};assert free>sum(sizes.values())+4*1024**3
R.mkdir()
for n in ['source','evidence','helper','artifacts','tmp']:(R/n).mkdir()
for n in ['kernel','out']:subprocess.run(['cp','-a',str(F/n),str(R/n)],check=True)
count=0
for group in ['kernel','out']:
 for root,ds,ns in os.walk(R/group,followlinks=False):
  for name in ns:
   p=Path(root)/name;old=F/p.relative_to(R)
   if p.is_symlink():continue
   assert p.stat().st_ino!=old.stat().st_ino and p.stat().st_mtime_ns==old.stat().st_mtime_ns;count+=1
for n in ['init','ram_pid1.c','run_identity.h']:shutil.copyfile(F/'helper'/n,R/'helper'/n)
for n in ['ramdisk.wrapped','initramfs.cpio.gz']:shutil.copyfile(F/'artifacts'/n,R/'artifacts'/n)
assert sha(R/'helper/init')=='37e9e2a2d73447947fb33e57e9513fa6079517b571f5a41bc58fbb91f84633fc'
assert (R/'out/arch/arm64/boot/dts/mediatek/asus-p00a.dtb').read_bytes()==(F/'out/arch/arm64/boot/dts/mediatek/asus-p00a.dtb').read_bytes()
for n,b64 in {'requested.config': '', 'link-dependencies.fragment': ''}.items():(R/'source'/n).write_bytes(base64.b64decode(b64))
assert sha(R/'source/requested.config')=='80bb4ae33a870ba8cfb44d65677f5e5e346ef0ebc6c411de7b4a13fe858e8e23'
shutil.copyfile(R/'source/requested.config',O/'.config')
env=dict(os.environ,ARCH='arm64',SRCARCH='arm64',KERNELVERSION='4.9.337',srctree=str(K),objtree=str(O),KCONFIG_CONFIG=str(O/'.config'),CC='aarch64-linux-gnu-gcc',HOSTCC='gcc')
cmd=[str(O/'scripts/kconfig/conf'),'--olddefconfig','Kconfig']
q=subprocess.run(cmd,cwd=K,env=env,text=True,capture_output=True);assert q.returncode==0,q.stderr
parse=lambda s:{m[1]:(m[2] or 'n') for m in re.finditer(r'^(?:# )?CONFIG_(\w+)(?:=(.*)| is not set)$',s,re.M)}
before=(F/'out/.config').read_text();after=(O/'.config').read_text();a=parse(before);b=parse(after)
delta={k:dict(before=a.get(k,'n'),after=b.get(k,'n')) for k in sorted(a.keys()|b.keys()) if a.get(k,'n')!=b.get(k,'n')}
newy=[k for k,v in delta.items() if v['after']=='y']
record=dict(status='RESOLVED_PENDING_VALUE_AND_DEFAULT_GATE',command=cmd,olddefconfig_calls=1,stdout=q.stdout,stderr=q.stderr,free_before=free,copied_sizes=sizes,independent_files_mtime_checked=count,no_cmd_rewrite_or_timestamps_changed=True,requested_sha256=sha(R/'source/requested.config'),resolved_sha256=sha(O/'.config'),delta=delta,new_y_symbols=newy)
(E/'initial-config-resolution.json').write_text(json.dumps(record,indent=2)+'\n');(E/'config-vs-r2.patch').write_text(''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='r2/.config',tofile='r3/.config')))
# Bind only the remaining direct source/default edges.
extra={}
for n in ['kernel/trace/ring_buffer.c','net/Kconfig','net/core/Makefile','net/Makefile','drivers/misc/mediatek/Makefile']:
 p=K/n
 if p.is_file():d=p.read_bytes();extra['evidence/source-facts/'+n]=d
battery=K/'drivers/power/supply/mediatek/battery/battery_meter.c';ls=battery.read_text().splitlines();hits=[]
for i,l in enumerate(ls):
 if 'netdevice_notifier' in l:hits.append(dict(line=i+1,context='\n'.join(ls[max(0,i-8):min(len(ls),i+8)])))
record['battery_source_sha256']=sha(battery);record['battery_notifier_contexts']=hits
# Only references to this cooler's public symbol/name in the thermal scope; no source sweep elsewhere.
refs=[]
for p in (K/'drivers/misc/mediatek/thermal').rglob('*.c'):
 for i,l in enumerate(p.read_text(errors='replace').splitlines()):
  if re.search(r'backlight_list_head|lcd-backlight[01]|virtual_sensor_cooler_backlight_(?:init|exit|register|unregister)',l):refs.append(dict(path=str(p.relative_to(K)),line=i+1,text=l))
record['cooler_scoped_references']=refs
files={};paths={'artifacts/resolution1.config':O/'.config'}
for p in E.glob('*'):paths['evidence/'+p.name]=p
for n,p in paths.items():extra[n]=p.read_bytes()
for n,d in extra.items():files[n]=dict(data=base64.b64encode(d).decode(),sha256=hashlib.sha256(d).hexdigest())
print(json.dumps(dict(files=files,config=record)))
